  "claims": [
    {
      "claim": "Glucose, a small polar sugar with active absorption, had oral bioavailability estimates of 0.722 in healthy subjects (C16), 0.843 in type 1 diabetic patients (C10), and 38% in hypoglycemic children (C15), all at or above the 20% threshold.",
      "card_ids": ["C10", "C15", "C16"]
    },
    {
      "claim": "Mannitol, a highly polar sugar alcohol, showed absolute oral bioavailability of 0.228 at 150 g and about 20% at 100 g (C01, C06, C09, C17), and sorbitol showed 0.36–0.38 in shunted patients (C03, C19), indicating that small polyhydroxy compounds can meet the F ≥ 20% threshold despite low passive permeability.",
      "card_ids": ["C01", "C03", "C06", "C09", "C17", "C19"]
    },
    {
      "claim": "Propylene glycol, a small polyol, was inferred to have very high oral bioavailability (C13), providing additional support that small polar polyhydroxy compounds can be well absorbed.",
      "card_ids": ["C13"]
    },
    {
      "claim": "Gemcitabine's low oral bioavailability (10%, range 5–17%) is attributed to first-pass metabolism by cytidine deaminase and high first-pass clearance (C07, C18, C20, C21), a mechanism not applicable to ascorbic acid; these low outcomes therefore do not transfer.",
      "card_ids": ["C07", "C18", "C20", "C21"]
    }
  ],
